#!/usr/bin/env bash
#
# Copyright 2026 Specfuse Contributors
# Licensed under the Apache License, Version 2.0. See LICENSE.
#
# Prove the C# starter contract (templates/component-contract/csharp/) in both
# directions: seeded into a minimal component tree shaped like the one
# docs/csharp-component-guide.md describes, every rule is green; and the
# template's own mutation test makes every rule fail on cue.
#
# The synthetic tree carries the layout the guide prescribes and nothing else:
# Directory.Build.props, three layered .csproj files, one generated file per
# layer with the generator's markers, a generated handler base with its
# hand-written subclass, and a generated application-service base with its
# subclass. No .NET SDK is needed; the contract reads files, not builds.
#
# Needs the engine: specfuse-loop 0.30+ importable by python3 (or by the
# interpreter named in SPECFUSE_PYTHON).
#
#   ./scripts/test-csharp-contract-template.sh
#
# Exit 0 when the seed is green and every mutation case passes.

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
KIT="$ROOT/templates/component-contract/csharp"
PY="${SPECFUSE_PYTHON:-python3}"
PREFIX=HelloOrders

if ! "$PY" -c "import specfuse.loop.gen_contract" >/dev/null 2>&1; then
  echo "test-csharp-contract-template: specfuse.loop.gen_contract is not importable by $PY" >&2
  echo "  python3 -m pip install 'specfuse-loop>=0.30'   (or set SPECFUSE_PYTHON)" >&2
  exit 2
fi

WORK="$(mktemp -d "${TMPDIR:-/tmp}/csharp-contract.XXXXXX")"
trap 'rm -rf "$WORK"' EXIT
cd "$WORK"
git init -q -b main .
git config user.email ci@example.invalid
git config user.name ci

# ── Seed the contract exactly as the template README says ──────────────────
cp "$KIT/gen-contract.yml" .
mkdir -p scripts docs .github/workflows
cp "$KIT/scripts/"* scripts/
cp "$KIT/docs/generated-code-expectations.md" docs/
cp "$KIT/.github/workflows/gen-contract.yml" .github/workflows/
sed -i.bak "s/__Prefix__/$PREFIX/g" gen-contract.yml docs/generated-code-expectations.md
rm -f gen-contract.yml.bak docs/generated-code-expectations.md.bak
chmod +x scripts/check-gen-contract.sh scripts/test-gen-contract.sh scripts/apply-gen-patches.sh

# ── A minimal component tree ───────────────────────────────────────────────
cat > Directory.Build.props <<'EOF'
<Project>
  <PropertyGroup>
    <EnableDefaultCompileItems>false</EnableDefaultCompileItems>
  </PropertyGroup>
  <ItemGroup>
    <Compile Include="src\**\*.cs" />
    <Compile Include="gen-src\**\*.cs" />
  </ItemGroup>
</Project>
EOF

cat > .gitignore <<'EOF'
bin/
obj/
EOF

header() {
  cat <<'EOF'
#nullable enable

// <auto-generated>
//   Generated = true
//   Generator = specfuse-generator
// </auto-generated>
/*
 * Generated by the Specfuse Generator (https://github.com/specfuse/generator)
 */
EOF
}

mkdir -p "$PREFIX.Domain/gen-src/Entities" "$PREFIX.Domain/src/Entities" \
         "$PREFIX.Infrastructure/gen-src/Repositories" "$PREFIX.Infrastructure/src" \
         "$PREFIX.Api/gen-src/Controllers" "$PREFIX.Api/gen-src/Application/Interfaces" "$PREFIX.Api/src/Application" \
         "$PREFIX.Application/gen-src/Orders/Handlers" "$PREFIX.Application/src/Orders/Handlers"

cat > "$PREFIX.Domain/$PREFIX.Domain.csproj" <<'EOF'
<Project Sdk="Microsoft.NET.Sdk">
</Project>
EOF
cat > "$PREFIX.Infrastructure/$PREFIX.Infrastructure.csproj" <<EOF
<Project Sdk="Microsoft.NET.Sdk">
  <ItemGroup>
    <ProjectReference Include="..\\$PREFIX.Domain\\$PREFIX.Domain.csproj" />
  </ItemGroup>
</Project>
EOF
cat > "$PREFIX.Api/$PREFIX.Api.csproj" <<EOF
<Project Sdk="Microsoft.NET.Sdk.Web">
  <ItemGroup>
    <ProjectReference Include="..\\$PREFIX.Domain\\$PREFIX.Domain.csproj" />
    <ProjectReference Include="..\\$PREFIX.Infrastructure\\$PREFIX.Infrastructure.csproj" />
  </ItemGroup>
</Project>
EOF

{ header; printf 'namespace %s.Domain.Entities;\n\npublic partial class Order { public Guid Id { get; set; } }\n' "$PREFIX"; } \
  > "$PREFIX.Domain/gen-src/Entities/Order.g.cs"
{ header; printf 'using %s.Domain.Entities;\n\nnamespace %s.Infrastructure.Repositories;\n\npublic class OrderRepository { }\n' "$PREFIX" "$PREFIX"; } \
  > "$PREFIX.Infrastructure/gen-src/Repositories/OrderRepository.g.cs"
{ header; printf 'using %s.Domain.Entities;\n\nnamespace %s.Api.Controllers;\n\npublic class OrdersApi { }\n' "$PREFIX" "$PREFIX"; } \
  > "$PREFIX.Api/gen-src/Controllers/OrdersApi.g.cs"
{ header; printf 'namespace %s.Api.Application.Interfaces;\n\npublic abstract class OrdersApplicationServiceBase { }\n' "$PREFIX"; } \
  > "$PREFIX.Api/gen-src/Application/Interfaces/OrdersApplicationServiceBase.g.cs"
{ header; printf 'namespace %s.Application.Orders.Handlers;\n\npublic interface IOrderPlacedHandler { }\npublic abstract class OrderPlacedHandlerBase : IOrderPlacedHandler { }\n' "$PREFIX"; } \
  > "$PREFIX.Application/gen-src/Orders/Handlers/OrderPlacedHandlerBase.g.cs"

printf 'namespace %s.Domain.Entities;\n\npublic partial class Order { public bool IsDraft => true; }\n' "$PREFIX" \
  > "$PREFIX.Domain/src/Entities/Order.cs"
printf 'namespace %s.Api.Application;\n\npublic sealed class OrdersApplicationService : OrdersApplicationServiceBase { }\n' "$PREFIX" \
  > "$PREFIX.Api/src/Application/OrdersApplicationService.cs"
printf 'namespace %s.Application.Orders.Handlers;\n\npublic sealed class OrderPlacedHandler(int x) : OrderPlacedHandlerBase { }\n' "$PREFIX" \
  > "$PREFIX.Application/src/Orders/Handlers/OrderPlacedHandler.cs"

git add -A
git commit -q -m "seed"

echo "── contract on the seeded tree"
./scripts/check-gen-contract.sh --quiet
echo "── every rule has a mutation case that bites"
status=0
out="$(./scripts/test-gen-contract.sh)" || status=$?
printf '%s\n' "$out"
if [ "$status" -ne 0 ] || ! grep -q ' 0 missed, 0 skipped' <<<"$out"; then
  echo "FAIL: a rule did not bite, or a case was skipped on the synthetic tree." >&2
  exit 1
fi

# ── Shapes the starter must accept, each committed on top of the seed and
# rolled back: the engine reads tracked files only.
echo "── variants that must stay green"
variant_green() {
  git add -A
  git commit -q -m "variant: $1"
  if ./scripts/check-gen-contract.sh --quiet; then
    echo "  ok    $1"
  else
    echo "FAIL: the contract rejects a valid shape: $1" >&2
    exit 1
  fi
  git reset -q --hard HEAD~1
}

cat > Directory.Build.props <<'EOF'
<Project>
  <PropertyGroup>
    <EnableDefaultCompileItems>false</EnableDefaultCompileItems>
  </PropertyGroup>
  <ItemGroup>
    <Compile Include="src/**/*.cs" />
    <Compile Include="gen-src/**/*.cs" />
  </ItemGroup>
</Project>
EOF
variant_green "forward-slash Compile globs"

mkdir -p "$PREFIX.UnitTests/src"
printf 'namespace %s.UnitTests;\n\npublic sealed class FakeOrderPlacedHandler : IOrderPlacedHandler { }\n' "$PREFIX" \
  > "$PREFIX.UnitTests/src/FakeOrderPlacedHandler.cs"
variant_green "a test double in a *UnitTests project"

git rm -q .gitignore
variant_green "no .gitignore at all"

# ── Temporary patches: every state apply-gen-patches.sh must tell apart ───
echo "── temporary patches"
expect_patches() {  # <exit> <text the output must contain> [args...]
  local code="$1" want="$2" out rc=0
  shift 2
  out="$(./scripts/apply-gen-patches.sh "$@" 2>&1)" || rc=$?
  if [ "$rc" -ne "$code" ] || ! grep -qF -- "$want" <<<"$out"; then
    echo "FAIL: apply-gen-patches.sh $*: wanted exit $code and '$want', got exit $rc:" >&2
    printf '%s\n' "$out" >&2
    exit 1
  fi
  echo "  ok    ${*:-(apply)}: $want"
}

ORDER="$PREFIX.Domain/gen-src/Entities/Order.g.cs"
PATCH=gen-patches/0001-order-id-init.patch
mkdir -p gen-patches
cp "$KIT/gen-patches/README.md" gen-patches/
expect_patches 0 "no patches"
sed -i.bak 's/{ get; set; }/{ get; init; }/' "$ORDER" && rm -f "$ORDER.bak"
{ printf 'Generator-Issue: clabonte/generator#1\nGenerator-Version: 0.19.0\nReason: Id must be init-only\n\n'
  git diff -- "$ORDER"; } > "$PATCH"
printf '| `0001-order-id-init.patch` | clabonte/generator#1 | 0.19.0 | Id is mutable |\n' >> gen-patches/README.md
git add -A
git commit -q -m "patch"

expect_patches 0 "ok               $PATCH" --check
./scripts/check-gen-contract.sh --quiet >/dev/null || { echo "FAIL: the contract rejects a tree with gen-patches/" >&2; exit 1; }

git show HEAD~1:"$ORDER" > "$ORDER"                       # a regen wiped the fix
expect_patches 1 "NOT APPLIED" --check
expect_patches 0 "" "$PREFIX.Api"                          # out of scope: left alone
expect_patches 1 "NOT APPLIED" --check
expect_patches 0 "applied          $PATCH"
expect_patches 0 "ok" --check

expect_patches 0 "already present  $PATCH"                 # the generator now emits the fix

git show HEAD~1:"$ORDER" | sed 's/public partial class Order/public sealed partial class Order/' > "$ORDER"
expect_patches 1 "FAILED           $PATCH"                 # the code around it changed
expect_patches 1 "STALE" --check
git checkout -q -- "$ORDER"

grep -vF '0001-order-id-init.patch' gen-patches/README.md > gen-patches/README.tmp && mv gen-patches/README.tmp gen-patches/README.md
expect_patches 1 "not listed in gen-patches/README.md" --check
git checkout -q -- gen-patches/README.md

sed -i.bak '/^Generator-Issue:/d' "$PATCH" && rm -f "$PATCH.bak"
expect_patches 1 "no 'Generator-Issue:' line" --check
git checkout -q -- "$PATCH"
git reset -q --hard HEAD~1

echo "OK: the C# starter contract is green on a fresh seed and every rule bites."
